    y0 = 40 + 26*r
    strip = img[y0:y0+26, 120:1170]
    b = strip > 100
    n = int(b.sum())
    if n == 0:
        return "empty"
    xmax = np.where(b.any(axis=0))[0]
    ymax = np.where(b.any(axis=1))[0]
    return f"{n:4d}px x{120+int(xmax.min())}-{120+int(xmax.max())} y{y0+int(ymax.min())}-{y0+int(ymax.max())}"

