import numpy as np
from PIL import Image
import os
import subprocess
import tempfile
import pickle
import re
import sys

def load_pgm(path):
    with open(path, 'rb') as f:
        data = f.read()
    parts = data.split(b'\n', 3)
    cols, rows = map(int, parts[1].split())
    img = np.frombuffer(parts[3], dtype=np.uint8)
    return img.reshape(rows, cols)

def pool(s):
    h, w = s.shape
    h2, w2 = h - (h % 2), w - (w % 2)
    s = s[:h2, :w2]
    return s.reshape(h2//2, 2, w2//2, 2).max(axis=(1, 3))

def find_cursor(strip):
    out = []
    H, W = strip.shape
    if strip.sum() < 20:
        return out
    for y in range(H):
        row = strip[y]
        if row.sum() < 11:
            continue
        xs = np.where(row)[0]
        i = 0
        while i < len(xs):
            j = i
            while j + 1 < len(xs) and xs[j+1] == xs[j] + 1:
                j += 1
            runlen = xs[j] - xs[i] + 1
            if 10 <= runlen <= 16:
                x0, x1 = xs[i], xs[j]
                y0 = y
                while y0 > 0 and strip[y0-1, x0:x1+1].sum() >= runlen - 2:
                    y0 -= 1
                y1 = y
                while y1 + 1 < H and strip[y1+1, x0:x1+1].sum() >= runlen - 2:
                    y1 += 1
                hgt = y1 - y0 + 1
                if 2 <= hgt <= 5:
                    above = strip[max(0, y0-4):y0, x0:x1+1].sum()
                    below = strip[y1+1:min(H, y1+5), x0:x1+1].sum()
                    if above <= 4 and below <= 4:
                        out.append((y0, y1, x0, x1))
                        break
            i = j + 1
    return out

