items = list(hash_rep.items())
for n, (h, (frame, screenrow)) in enumerate(items):
    s = get_raw(frame)[screenrow]
    txt = ocr_row(s, '7')
    if s.sum() < 120:
        t8 = ocr_row(s, '8')
        if len(t8) <= max(len(txt), 1) + 2:
            txt = t8 if t8 else txt
    ocr_cache[h] = txt
    if (n + 1) % 50 == 0:
        print(f"  OCR {n+1}/{len(items)}", file=sys.stderr)

text = [None if T[idx] is None else ocr_cache[T[idx]] for idx in range(len(T))]
with open('/app/stages/transcript_text.pkl', 'wb') as f:
    pickle.dump({'text': text, 'reps': reps}, f)
print("saved transcript_text.pkl")

