import numpy as np, pickle

def load_pgm(path):
    with open(path,'rb') as f: data=f.read()
    parts=data.split(b'\n',3)
    cols,rows=map(int,parts[1].split())
    return np.frombuffer(parts[3],dtype=np.uint8).reshape(rows,cols)

PITCH=(665.5-52.0)/24
def rowbox(i):  # page rows for line i (0-based)
    c=52+PITCH*i
    a=max(0,int(round(c-13))); b=min(719,int(round(c+13)))
    return a,b

_cache={}
def get_page(K1):  # K1 1-based frame number
    if K1 not in _cache:
        _cache[K1]=load_pgm(f'/app/frames/f{K1:04d}.pgm')
    return _cache[K1]

def row_cells(K1, li, x0=0, x1=1022):
    img=get_page(K1)
    a,b=rowbox(li)
    seg=(img>127)[a:b+1,128+x0:128+x1+1]
    H=seg.shape[0]
    pad=np.zeros((28,seg.shape[1]),bool)
    pad[:min(28,H),:]=seg[:28]
    cells=[]
    x=x0
    while x+13<=x1:
        cells.append(pad[:,x:x+13]); x+=13
    return cells, pad

def dist(a,b): return int((a!=b).sum())

# ---- templates from line 14 & 15 of f139 (known Zork opening)
texts1415=["You are standing in an open field west of a white",
           "house, with a boarded front door. There is a small mailbox here."]
templates={}
for li,txt in zip([14,15],texts1415):
    cells,_=row_cells(139,li)
    for i,ch in enumerate(txt):
        if i>=len(cells) or ch==' ': continue
        templates.setdefault(ch,[]).append(cells[i])
print("templates:", {k:len(v) for k,v in sorted(templates.items())})
# intra-template consistency
for ch,tl in sorted(templates.items()):
    if len(tl)>1:
        md=max(dist(tl[0],t) for t in tl)
        if md>10: print(f"  WARN {ch} intra {md}")

def classify_cell(c):
    if c.sum()<4: return ' ',0
    best=None;bd=1e9
    for ch,tl in templates.items():
        for t in tl:
            d=dist(c,t)
