img=load_pgm('/app/frames/f0139.pgm')
PITCH=(665.5-52.0)/24
def rowbox(i):
    c=52+PITCH*i
    return max(0,int(round(c-13))), min(719,int(round(c+13)))

# 13px grid, glyphs centered (drift up to 2px). Extract 15px window.
def cell(page, li, k, pad=1):
    a,b=rowbox(li)
    seg=(page>127)[a:b+1, 128:1152]
    H=seg.shape[0]
    W=seg.shape[1]
    c=np.zeros((28,15),bool)
    x0=13*k-pad; x1=13*k+13+pad
    xs=max(0,x0); xe=min(W,x1)
    h=min(28,H)
    c[:h,:]=False
    sub=seg[:h, xs:xe]
    c[:sub.shape[0], :sub.shape[1]]=sub
    return c

def dist15(a,b,shifts=range(-2,3)):
    # a,b are 28x15 (13px cell + 1px pad each side). Best shift over x in -2..2, y in -2..2
    bd=1e9
    for dx in shifts:
        for dy in shifts:
            am=a; bm=b
            if dx>=0:
                aa=a[:,dx:]; bb=b[:,:15-dx]
            else:
                aa=a[:,:15+dx]; bb=b[(-dx):,]
            if dy>=0:
                aa2=aa[dy:]; bb2=bb[:28-dy]
            else:
                aa2=aa[:28+dy]; bb2=bb[(-dy):,]
            d=int((aa2!=bb2).sum())
            if d<bd: bd=d
    return bd

