# self-test: classify each line's cells with templates from OTHER lines
for li,(txt,(a,b)) in lines.items():
    out=[];scores=[]
    for k,ch in enumerate(txt):
        if ch==' ':
            out.append(' ');scores.append(0);continue
        c=cell(img,li,k)
