import numpy as np, pickle, os

def load_pgm(path):
    with open(path,'rb') as f: data=f.read()
    parts=data.split(b'\n',3)
    cols,rows=map(int,parts[1].split())
    return np.frombuffer(parts[3],dtype=np.uint8).reshape(rows,cols)

PITCH=(665.5-52.0)/24
def rowbox(i):
    c=52+PITCH*i
    return max(0,int(round(c-13))), min(719,int(round(c+13)))

_cache={}
def get_page(K1):
    if K1 not in _cache:
        _cache[K1]=load_pgm(f'/app/frames/f{K1:04d}.pgm')
    return _cache[K1]

def strip(K, rr):
    img=get_page(K+1)
    a,b=rowbox(rr)
    return (img>127)[a:b+1,128:1152]

def has_chevron(s):
    reg=s[:,0:15]
    for o in range(0,16):
        r=reg[o:o+13]
        if r.sum()<25 or r.sum()>70: continue
        cents=[]
        for rr in range(r.shape[0]):
            row=r[rr]
            if row.sum()>=2:
                cc=np.where(row)[0]
                if cc.max()>12: continue
                cents.append(cc.mean())
        if len(cents)<6: continue
        if max(cents)-min(cents)<4: continue
        imax=cents.index(max(cents))
        if imax<2 or imax>len(cents)-3: continue
        return True
    return False

def char_cells(s):
    t=s[:,13:]
    H=s.shape[0]
    colsum=t.sum(axis=0)
    bottom=t[max(0,H-6):,:].sum(axis=0)
    iscursor=(colsum>=2)&(colsum<=8)&(bottom==colsum)
    if t.shape[0]<28:
        tt=np.zeros((28,t.shape[1]),bool); tt[:t.shape[0]]=t; t=tt
    cells=[]
    for k in range(14):
        x0=13*k
        if x0+13>t.shape[1]: break
        c=np.zeros((28,15),bool)
        xs=max(0,x0-1); xe=min(t.shape[1],x0+14)
        if iscursor[xs:xe].all() and colsum[xs:xe].sum()<=24:
            continue
        c[:, :xe-xs]=t[:, xs:xe]
        cells.append(c)
    return cells

with open('/app/stages/templates.pkl','rb') as f: templates=pickle.load(f)

def dist15(a_,b_):
    bd=1e9
    for dx in range(-3,4):
        for dy in range(-6,7):
            i0=max(0,dy); i1=min(28,28+dy)
            j0=max(0,dx); j1=min(15,15+dx)
            if i1<=i0 or j1<=j0: continue
            d=int((a_[i0:i1,j0:j1] != b_[i0-dy:i1-dy, j0-dx:j1-dx]).sum())
            if d<bd: bd=d
    return bd

def classify(c):
    if c.sum()<4: return ' ',0
    best='?'; bd=1e9
    for ch,tl in templates.items():
        for t in tl:
            d=dist15(c,t)
            if d<bd: bd=d; best=ch
    return best,bd

def read_line(s):
    cells=char_cells(s)
    out=[];scores=[]
    for c in cells:
        ch,sc=classify(c)
        out.append(ch);scores.append(sc)
    while out and out[-1]==' ': out.pop(); scores.pop()
    return ''.join(out), scores, [int(c.sum()) for c in cells]

with open('/app/stages/move_frames2.pkl','rb') as f: CMD=pickle.load(f)
results=[]
for idx,F in enumerate(CMD):
    cands=[]
    for K in range(max(0,F-8), F+5):
        for rr in [24,23,22]:
            s=strip(K,rr)
            if not has_chevron(s): continue
            txt,sc,inks=read_line(s)
            ci=sum(i for i in inks if i>=4)
            cands.append((K,rr,ci,txt,sc))
    # priority: (K<=F and rr==24) most chars; then rr 23 at K in F..F+2; then anything
    def prio(c):
        K,rr,ci,txt,sc=c
        if K<=F and rr==24 and ci>=18: return (0,len(txt),K)
        if rr==23 and F<=K<=F+2 and ci>=18: return (1,len(txt),K)
        if ci>=18: return (2,len(txt),K)
        return (3,0,K)
    best=None
    for c in cands:
        p=prio(c)
        if best is None or p<best[0]: best=(p,c)
    p,c=best if best else (None,None)
    if c is None:
        results.append((F,None,'','none'))
        print(f"f{F:4d}: NO CANDIDATE")
        continue
    K,rr,ci,txt,sc=c
    bad=[(i,x,s3) for i,(x,s3) in enumerate(zip(txt,sc)) if s3>25]
    results.append((F,K,txt,f'r{rr}' if not bad else f'r{rr}low{bad}'))
    print(f"f{F:4d} (f{K:4d} r{rr}): {txt!r}"+(f"  {bad}" if bad else ""))
with open('/app/stages/commands.pkl','wb') as f: pickle.dump(results,f)
print("DONE",len(results))

